WITH latest_match AS (SELECT s.*, latest.txn_time FROM accounts s LEFT JOIN LATERAL (SELECT c.txn_time FROM transactions c WHERE c.account_id = s.id ORDER BY c.amount DESC, c.id DESC LIMIT 1) latest ON TRUE) SELECT id, account_type, balance, status, txn_time, CASE WHEN status RLIKE '^(FROZEN|OPEN)$' THEN 'EXTENDED' WHEN status RLIKE '^(CLOSED)$' THEN 'GROUP_B' ELSE 'CORE' END AS status_zone FROM latest_match ORDER BY status DESC NULLS FIRST
